catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

	g_form.addInfoMessage('BP PEAR ' + newValue);
	var ga = new GlideAjax('PEAR_Utils2');
	ga.addParam('sysparm_name', 'isProjectRequiredByBusinessProfile');
	// ga.addParam('sysparm_name', 'getProjectsByBusinessProfile');
    ga.addParam('sysparm_BusinessProfileId', newValue);
    ga.getXMLAnswer(function(answer) {
		var isRequired = (answer === 'true');
		g_form.addInfoMessage('Project required? ' + isRequired);
		g_form.setVisible('projects', isRequired);
		g_form.setMandatory('projects', isRequired);		

    });


   //Type appropriate comment here, and begin script below

}
